CREATE TABLE IF NOT EXISTS money_fdh_document (kind ENUM('rep','stm') NOT NULL, doc_no VARCHAR(100) NOT NULL, hcode CHAR(5) NULL, hname VARCHAR(255) NOT NULL, period VARCHAR(50) NOT NULL, report_date DATE NULL, file_name VARCHAR(255) NOT NULL, item_count INT NOT NULL, money_sum DECIMAL(15,2) NOT NULL, document_ciphertext LONGTEXT NOT NULL, uploaded_at DATETIME NOT NULL, uploaded_by CHAR(36) NOT NULL, PRIMARY KEY (kind, doc_no), CONSTRAINT money_fdh_document_person_fk FOREIGN KEY (uploaded_by) REFERENCES person(id)) DEFAULT CHARSET=utf8mb4;
